sys_script_include.script:
var PinCodeHelper = Class.create();
PinCodeHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getLocationByPin: function() {
        var pincode = this.getParameter('sysparm_postal_code');
        var response = new sn_ws.RESTMessageV2(); // REST call to postal API
        response.setHttpMethod('GET');
        response.setEndpoint('https://api.postalpincode.in/pincode/' + pincode);

        var resp = response.execute();
        var body = resp.getBody();

        var json = JSON.parse(body);
        var result = {};
        if (json[0].Status === 'Success') {
            var postOffice = json[0].PostOffice[0];
            result.city = postOffice.Division;


            result.state = postOffice.State;
        } else {
            result.error = true;
        }
        return JSON.stringify(result);
    },
    setRestaurant: function() {
        var restaurantSysId = this.getParameter('sysparm_restaurant_sys_id');
        if (restaurantSysId) {
            gs.info('Restaurant Sys_id : ' + restaurantSysId);
            gs.getSession().putClientData('selected_restaurant', restaurantSysId + '');
        }
        return 'Success!!!!';
    },
    getMenuDetails: function() {
		var result = {};
        var menuSysId = this.getParameter('sysparm_menu_name_sys_id');
        var menu = new GlideRecord('x_946454_food_de_0_menu_items');
        //menu.addQuery('sys_id',menuSysId+'');
        menu.addQuery('sys_id', menuSysId);
        menu.query();
        gs.info(menu.query);
        gs.info('Menu :' + menuSysId + '');
        if (menu.next()) {
            result.ingredients = menu.ingredients + '';
            result.price = menu.price + '';
        }
        gs.info("Result : "+result);
        return JSON.stringify(result);
    },


    type: 'PinCodeHelper'

});
